CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL, status TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(email TEXT PRIMARY KEY, attempts INTEGER NOT NULL, reset_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS stores(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL, reason TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS members(store_id TEXT NOT NULL REFERENCES stores(id), user_id TEXT NOT NULL REFERENCES users(id), permission TEXT NOT NULL, PRIMARY KEY(store_id,user_id));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(id), name TEXT NOT NULL, category TEXT NOT NULL, brand TEXT NOT NULL, description TEXT NOT NULL, attributes TEXT NOT NULL, sku TEXT NOT NULL, price BIGINT NOT NULL CHECK(price>0), mrp BIGINT NOT NULL CHECK(mrp>=price), stock INTEGER NOT NULL CHECK(stock>=0), status TEXT NOT NULL, moderation TEXT NOT NULL, image TEXT NOT NULL, version INTEGER NOT NULL, created BIGINT NOT NULL, UNIQUE(store_id,sku));
CREATE TABLE IF NOT EXISTS stock_moves(id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id), delta INTEGER NOT NULL, reason TEXT NOT NULL, actor TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS media(id TEXT PRIMARY KEY, owner TEXT NOT NULL, mime TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS addresses(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), label TEXT NOT NULL, address TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wishlist(user_id TEXT NOT NULL REFERENCES users(id), product_id TEXT NOT NULL REFERENCES products(id), PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS carts(user_id TEXT NOT NULL REFERENCES users(id), product_id TEXT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity>0), PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS coupons(code TEXT PRIMARY KEY, percent INTEGER NOT NULL CHECK(percent BETWEEN 1 AND 80), max_discount BIGINT NOT NULL, minimum BIGINT NOT NULL, max_uses INTEGER NOT NULL, uses INTEGER NOT NULL, active INTEGER NOT NULL, expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), address TEXT NOT NULL, total BIGINT NOT NULL, discount BIGINT NOT NULL, coupon TEXT NOT NULL, payment TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), store_id TEXT NOT NULL REFERENCES stores(id), product_id TEXT NOT NULL REFERENCES products(id), name TEXT NOT NULL, quantity INTEGER NOT NULL, price BIGINT NOT NULL, total BIGINT NOT NULL, status TEXT NOT NULL, courier_id TEXT, otp_hash TEXT NOT NULL, otp_attempts INTEGER NOT NULL, otp_expires BIGINT NOT NULL, cod_collected INTEGER NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS checkout_keys(user_id TEXT NOT NULL, key TEXT NOT NULL, fingerprint TEXT NOT NULL, order_id TEXT NOT NULL REFERENCES orders(id), PRIMARY KEY(user_id,key));
CREATE TABLE IF NOT EXISTS coupon_uses(user_id TEXT NOT NULL, code TEXT NOT NULL, order_id TEXT NOT NULL, PRIMARY KEY(user_id,code));
CREATE TABLE IF NOT EXISTS returns(id TEXT PRIMARY KEY, item_id TEXT UNIQUE NOT NULL REFERENCES order_items(id), reason TEXT NOT NULL, status TEXT NOT NULL, disposition TEXT NOT NULL, refund BIGINT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(id), item_id TEXT NOT NULL, kind TEXT NOT NULL, amount BIGINT NOT NULL, created BIGINT NOT NULL, UNIQUE(item_id,kind));
CREATE TABLE IF NOT EXISTS payouts(id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(id), amount BIGINT NOT NULL, requested_by TEXT NOT NULL, status TEXT NOT NULL, approved_by TEXT, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), product_id TEXT NOT NULL REFERENCES products(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), body TEXT NOT NULL, status TEXT NOT NULL, created BIGINT NOT NULL, UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS tickets(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), subject TEXT NOT NULL, status TEXT NOT NULL, messages TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), message TEXT NOT NULL, seen INTEGER NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, detail TEXT NOT NULL, created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS items_store ON order_items(store_id,status);
CREATE INDEX IF NOT EXISTS items_courier ON order_items(courier_id,status);
CREATE INDEX IF NOT EXISTS orders_user ON orders(user_id,created);
CREATE INDEX IF NOT EXISTS notifications_user ON notifications(user_id,created);
